package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.File;
import java.io.FileOutputStream;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.security.cert.X509CRL;
import java.time.Instant;
import java.util.Collections;
import java.util.Date;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.jar.JarOutputStream;
import java.util.zip.ZipEntry;

import org.bouncycastle.asn1.x500.X500Name;
import org.eclipse.kura.core.keystore.util.CRLUtil;
import org.eclipse.kura.core.testutil.pki.TestCA;
import org.eclipse.kura.core.testutil.pki.TestCA.CRLCreationOptions;
import org.eclipse.kura.core.testutil.pki.TestCA.CertificateCreationOptions;
import org.junit.After;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CrlUrlSchemeTest {

    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    private X509CRL crl;
    private URI crlUri;
    private CompletableFuture<X509CRL> fetchResult;

    @After
    public void shutdownExecutor() {
        this.executor.shutdownNow();
    }

    @Test
    public void crlIsFetchedFromFileUrl() throws Exception {
        givenCrl();
        givenCrlPublishedAsFile();

        whenCrlIsFetched();

        thenFetchedCrlIsThePublishedOne();
    }

    @Test
    public void crlIsFetchedFromJarUrl() throws Exception {
        givenCrl();
        givenCrlPublishedInsideJar();

        whenCrlIsFetched();

        thenFetchedCrlIsThePublishedOne();
    }

    @Test
    public void crlUrlWithUnknownProtocolFails() throws Exception {
        givenUnknownProtocolUri();

        whenCrlIsFetched();

        thenFetchFails();
    }

    private void givenCrl() throws Exception {
        final TestCA ca = new TestCA(CertificateCreationOptions.builder(new X500Name("cn=Test CA, dc=bar.com")).build());

        this.crl = ca.generateCRL(CRLCreationOptions.builder().withStartDate(Date.from(Instant.now().minusSeconds(60)))
                .withEndDate(Date.from(Instant.now().plusSeconds(3600))).build());
    }

    private void givenCrlPublishedAsFile() throws IOException {
        final File file = this.temporaryFolder.newFile("test.crl");

        try (final FileOutputStream out = new FileOutputStream(file)) {
            TestCA.encodeToPEM(this.crl, out);
        }

        this.crlUri = file.toURI();
    }

    private void givenCrlPublishedInsideJar() throws IOException {
        final File jar = this.temporaryFolder.newFile("crl.jar");

        try (final JarOutputStream out = new JarOutputStream(new FileOutputStream(jar))) {
            out.putNextEntry(new ZipEntry("test.crl"));
            TestCA.encodeToPEM(this.crl, new NonClosingOutputStream(out));
            out.closeEntry();
        }

        this.crlUri = URI.create("jar:" + jar.toURI() + "!/test.crl");
    }

    private void givenUnknownProtocolUri() {
        this.crlUri = URI.create("unknown://localhost/test.crl");
    }

    private void whenCrlIsFetched() {
        this.fetchResult = CRLUtil.fetchCRL(Collections.singleton(this.crlUri), this.executor);
    }

    private void thenFetchedCrlIsThePublishedOne() throws Exception {
        assertEquals(this.crl, this.fetchResult.get(30, TimeUnit.SECONDS));
    }

    private void thenFetchFails() throws Exception {
        try {
            this.fetchResult.get(30, TimeUnit.SECONDS);
            fail("expected the CRL fetch from " + this.crlUri + " to fail");
        } catch (final ExecutionException e) {
            assertTrue(e.getCause() instanceof IOException);
        }
    }

    private static class NonClosingOutputStream extends FilterOutputStream {

        NonClosingOutputStream(final OutputStream out) {
            super(out);
        }

        @Override
        public void close() throws IOException {
            flush();
        }
    }
}
